<template>
  <div class="settings-card">
    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('delete_document_after') }}</span>
      </div>
      <div class="settings-toggle-selects">
        <q-select
          outlined
          dense
          class="back-white"
          v-model="user_settings[document_expiry_setting]"
          :options="date_range_options"
          @update:model-value="
            save(
              document_expiry_setting,
              user_settings[document_expiry_setting],
            )
          "
          emit-value
          map-options
        />
      </div>
    </div>

    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('delete_finished_document_after') }}</span>
      </div>
      <div class="settings-toggle-selects">
        <q-select
          outlined
          dense
          class="back-white"
          v-model="user_settings[finished_document_expiry_setting]"
          :options="date_range_options"
          @update:model-value="
            save(
              finished_document_expiry_setting,
              user_settings[finished_document_expiry_setting],
            )
          "
          emit-value
          map-options
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { isUndefinedOrNull } from 'src/utils/general';
import {
  document_expiry_setting,
  finished_document_expiry_setting,
} from 'src/constants';
export default defineComponent({
  mixins: [helperMixin],
  data() {
    return {
      document_expiry_setting,
      finished_document_expiry_setting,
    };
  },
  mounted: function () {
    this.init();
  },

  methods: {
    init() {
      if (isUndefinedOrNull(this.user_settings[this.document_expiry_setting])) {
        this.user_settings[this.document_expiry_setting] = 'none';
      }

      if (
        isUndefinedOrNull(
          this.user_settings[this.finished_document_expiry_setting],
        )
      ) {
        this.user_settings[this.finished_document_expiry_setting] = 'none';
      }

      this.date_range_options = [
        {
          label: '',
          value: 'none',
        },
        {
          label: this.$t('default'),
          value: 'default',
        },
        {
          label: this.$t('hours_48'),
          value: '172800',
        },
        {
          label: this.$t('week_1'),
          value: '604800',
        },
        {
          label: this.$t('week_2'),
          value: '1209600 ',
        },
        {
          label: this.$t('week_4'),
          value: '2419200',
        },
      ];
    },
    async save(key: string, value: string) {
      try {
        this.showLoading();
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;
    return {
      updateSetting,
      user_settings,
      loading_settings,
      date_range_options: ref([] as dynamicObj[]),
    };
  },
});
</script>
